@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

abstract class EntryValue {}

class TextualInformation extends EntryValue {}

class NumericalValue extends EntryValue {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + emailAddress : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : has
WebPortal "1" -- "*" Visitor : has
WebPortal "1" -- "*" Comment : contains

Building "1" *-- "*" AdditionalEntry : has
Building "1" *-- "*" Image : has
Building "1" -- "1" Image : profile photo

User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has

Visitor "0..1" -- "0..*" Building : searches
Visitor "0..1" -- "0..*" Comment : views

@enduml

